from __future__ import annotations
import hashlib, json
from pathlib import Path
import nbformat
ROOT = Path(__file__).resolve().parent
SOURCE = ROOT / 'download_test.py'
TEMPLATE = Path('experiments/spi_classifier_repair/runs/notebook9_20261028_v15/submission_v15_cnn_compare')
OUT = ROOT / 'notebooks' / 'notebook9_dataset_download_test.ipynb'
META_OUT = ROOT / 'runs' / 'notebook9_download_test_20261028' / 'kernel-metadata.json'
source_text = SOURCE.read_text(encoding='utf-8')
source_hash = hashlib.sha256(source_text.encode('utf-8')).hexdigest()
metadata = json.loads((TEMPLATE / 'kernel-metadata.json').read_text(encoding='utf-8'))
metadata.update({'code_file':'notebook.ipynb','enable_gpu':False,'enable_internet':True,'dataset_sources':['satyapaladugu/betterscheduler-spiv2-inputs-20261027b'],'competition_sources':[],'kernel_sources':[]})
metadata.pop('machine_shape', None)
META_OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.parent.mkdir(parents=True, exist_ok=True)
META_OUT.write_text(json.dumps(metadata, indent=2) + '\n', encoding='utf-8')
md = '''# Kaggle full source download test\n\nCPU-only preflight on the established notebook9 identity. It attempts all LADI-v2 data files and the complete official MEDIC and CrisisMMD archives, writes only under `/kaggle/working/experiments/dataset_detector_grid/runs/<UTC run id>/`, and maintains a 3 GB free-space reserve. It does not extract archives, train models, or retrieve image archives to the laptop.\n\nThe existing private input dataset remains attached for identity continuity; this test downloads from the published source URLs.\n'''
setup = f'''# Setup, provenance, and bounded runtime directory\nimport hashlib, json, os, platform, shutil, sys, time, traceback\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nSOURCE_TEXT = {json.dumps(source_text, ensure_ascii=True)}\nEXPECTED_SOURCE_SHA256 = {source_hash!r}\nactual_source_sha256 = hashlib.sha256(SOURCE_TEXT.encode("utf-8")).hexdigest()\nassert actual_source_sha256 == EXPECTED_SOURCE_SHA256, "embedded download source hash mismatch"\nrun_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "_dataset_download"\nrun_root = Path("/kaggle/working/experiments/dataset_detector_grid/runs") / run_id\nrun_root.mkdir(parents=True, exist_ok=False)\nlog_path = run_root / "stdout.log"\nclass Tee:\n    def __init__(self, *streams): self.streams = streams\n    def write(self, value):\n        for stream in self.streams: stream.write(value); stream.flush()\n        return len(value)\n    def flush(self):\n        for stream in self.streams: stream.flush()\n    def isatty(self): return False\n    @property\n    def encoding(self): return getattr(self.streams[0], "encoding", "utf-8")\n\nlog_file = log_path.open("a", encoding="utf-8", buffering=1)\n_original_stdout, _original_stderr = sys.stdout, sys.stderr\nsys.stdout = Tee(_original_stdout, log_file)\nsys.stderr = Tee(_original_stderr, log_file)\ndisk = shutil.disk_usage("/kaggle/working")\nprint("PREFLIGHT START", run_id, flush=True)\nprint(json.dumps({{"python_executable": sys.executable, "python_version": sys.version, "platform": platform.platform(), "requests": __import__("requests").__version__, "run_root": str(run_root), "source_sha256": actual_source_sha256, "free_bytes_before": disk.free, "reserve_bytes": 3000000000, "download_budget_seconds": 3600}}, sort_keys=True), flush=True)\n(run_root / "provenance.json").write_text(json.dumps({{"run_id": run_id, "source_sha256": actual_source_sha256, "python_executable": sys.executable, "python_version": sys.version, "platform": platform.platform(), "free_bytes_before": disk.free, "reserve_bytes": 3000000000, "download_budget_seconds": 3600, "notebook_ref": "satyapaladugu/betterscheduler-spi-20261027finalc", "gpu_enabled": False}}, indent=2), encoding="utf-8")\n'''
run = '''# Execute the exact committed source with incremental logging and failure receipt\nimport json, shutil, time, traceback\nrun_started = time.monotonic()\nreserve = 3_000_000_000\nfree_before = shutil.disk_usage("/kaggle/working").free\nif free_before < reserve:\n    result = {"status": "insufficient_initial_disk", "free_bytes_before": free_before, "reserve_bytes": reserve}\n    (run_root / "summary.json").write_text(json.dumps(result, indent=2), encoding="utf-8")\n    print("DOWNLOAD SKIPPED: initial free space is below the required reserve", flush=True)\nelse:\n    try:\n        namespace = {"__name__": "kaggle_dataset_download_test"}\n        exec(compile(SOURCE_TEXT, "download_test.py", "exec"), namespace)\n        namespace["run"](run_root, seconds=3600)\n        print("DOWNLOAD TEST FUNCTION COMPLETED", flush=True)\n    except BaseException as error:\n        failure = {"status": "runner_exception", "error_type": type(error).__name__, "message": str(error), "traceback": traceback.format_exc(), "elapsed_seconds": time.monotonic() - run_started, "free_bytes": shutil.disk_usage("/kaggle/working").free}\n        (run_root / "runner_failure.json").write_text(json.dumps(failure, indent=2), encoding="utf-8")\n        print("DOWNLOAD TEST FAILED; traceback saved", flush=True)\n        traceback.print_exc()\nfree_after = shutil.disk_usage("/kaggle/working").free\nrun_summary = {"elapsed_seconds": time.monotonic() - run_started, "free_bytes_after": free_after, "reserve_bytes": reserve, "reserve_preserved": free_after >= reserve, "run_root": str(run_root)}\n(run_root / "notebook_summary.json").write_text(json.dumps(run_summary, indent=2), encoding="utf-8")\nprint("DOWNLOAD TEST CELL COMPLETE", json.dumps(run_summary, sort_keys=True), flush=True)\n'''
nb = nbformat.v4.new_notebook(cells=[nbformat.v4.new_markdown_cell(md),nbformat.v4.new_code_cell(setup),nbformat.v4.new_code_cell(run)])
nb.metadata.update({'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python'},'codex':{'purpose':'CPU-only full-source dataset download feasibility test on existing notebook9 identity','source_sha256':source_hash,'timeout_seconds':3600,'aggregate_gpu_hour_cap':0,'experiment_plan':'experiments/dataset_detector_grid/PLAN.md'}})
nbformat.write(nb, OUT)
print(OUT)
print(META_OUT)
print('source_sha256', source_hash)
print('notebook_sha256', hashlib.sha256(OUT.read_bytes()).hexdigest())


